/**
 * Cross-language parity test for the dedup key.
 *
 * supabase/functions/_shared/normalize.ts (TypeScript, runs in edge functions)
 * and public.make_dedup_key() (SQL, runs during backfills) must produce
 * IDENTICAL keys. If they ever drift, a SQL backfill computes different keys
 * than the ingest path and silently double-counts transactions.
 *
 * Run:  node --experimental-strip-types scripts/test-dedup-parity.mjs
 *
 * The expected values below were generated by BOTH implementations and verified
 * to agree. If you change either side, regenerate and re-verify both.
 */
import { makeDedupKey } from '../supabase/functions/_shared/normalize.ts';

const USER = '00000000-0000-0000-0000-000000000001';
const ACCT = '00000000-0000-0000-0000-000000000002';

/** name, key inputs, value produced by the SQL function */
const CASES = [
  {
    name: 'plain row',
    input: { userId: USER, accountId: ACCT, occurredAt: '2026-06-28T19:10:52Z', amount: 58, description: 'Grocery', occurrence: 0 },
    sql: 'e024c00b6ed6cb29a5ef4943da1fab7bf43c2b9b4f4205458e9c9e2269e2c1a3',
  },
  {
    name: 'null account, occurrence index, trailing whitespace',
    input: { userId: USER, accountId: null, occurredAt: '2024-05-15T17:46:43Z', amount: 542.5, description: 'Charges, Fees  ', occurrence: 1 },
    sql: 'ad5399d22ecad9e5267e817eff6bf38b4e2265de3621a9d9f61f111edaae709d',
  },
  {
    name: 'thousands separator, shouting punctuation',
    input: { userId: USER, accountId: ACCT, occurredAt: '2026-01-01T00:00:00Z', amount: 1234.56, description: 'RADHIKAPUR   EXPRESS!!!', occurrence: 0 },
    sql: '6f90b24ba8dbfd74b1f24a92a1c5ba3a3f2892842dc07b441b8f29509acf7754',
  },
];

let fails = 0;
for (const c of CASES) {
  const ts = await makeDedupKey({
    userId: c.input.userId,
    accountId: c.input.accountId,
    occurredAt: new Date(c.input.occurredAt),
    amount: c.input.amount,
    description: c.input.description,
    occurrence: c.input.occurrence,
  });
  const ok = ts === c.sql;
  console.log(`  ${ok ? 'ok  ' : 'FAIL'} ${c.name}`);
  if (!ok) {
    fails++;
    console.log(`       ts  = ${ts}`);
    console.log(`       sql = ${c.sql}`);
  }
}

console.log(fails === 0 ? '\nDEDUP PARITY OK' : `\n${fails} PARITY FAILURE(S)`);
process.exit(fails === 0 ? 0 : 1);
